def build_query(params):
    parts = []
    for key in sorted(params):
        value = params[key]
        if value is None:
            continue
        if isinstance(value, (list, tuple)):
            text = ','.join(quote(str(v), safe='') for v in value)
        else:
            text = quote(str(value), safe='')
        parts.append(f'{quote(str(key), safe="")}={text}')
