import re


def parts(v):
    return [int(x) for x in v.split('.')]


def _key(v):
    v = v.strip().lstrip('vV')
    main, _, pre = v.partition('-')
    nums = parts(main)
    while len(nums) < 3:
        nums.append(0)
    if pre:
        m = re.search(r'(\d+)$', pre)
        return (nums, 0, int(m.group(1)) if m else 0)
    return (nums, 1, 0)


def is_newer(a, b):
    return _key(a) > _key(b)

